"""Summarize node sequence gaps without modifying the node."""
import json
import os
from pathlib import Path
import re
import sys


def reject_constant(value):
    raise ValueError(value)


def records(node, name, bad):
    segments = []
    active = None
    pattern = re.compile(re.escape(name) + r"\.[0-9]{12}\.jsonl\Z")
    with os.scandir(node) as entries:
        for entry in entries:
            if not entry.is_file(follow_symlinks=False):
                continue
            if pattern.fullmatch(entry.name):
                segments.append(entry.name)
            elif entry.name == name + ".active.jsonl":
                active = entry.name
    files = sorted(segments)
    if active is not None:
        files.append(active)
    seqs = []
    for filename in files:
        parts = (node / filename).read_bytes().split(b"\n")
        for number, line in enumerate(parts[:-1], 1):
            try:
                value = json.loads(line, parse_constant=reject_constant)
            except (ValueError, UnicodeError):
                bad.append({"file": filename, "line": number, "why": "bad_json"})
                continue
            seq = value.get("seq") if isinstance(value, dict) else None
            if type(seq) is not int or seq < 1:
                bad.append({"file": filename, "line": number, "why": "no_seq"})
            else:
                seqs.append(seq)
        if parts[-1]:
            bad.append({"file": filename, "line": len(parts), "why": "torn"})
    return seqs


def channel_result(seqs):
    distinct = sorted(set(seqs))
    missing = [[left + 1, right - 1] for left, right in zip(distinct, distinct[1:])
               if right > left + 1]
    counts = {}
    for seq in seqs:
        counts[seq] = counts.get(seq, 0) + 1
    return {"count": len(seqs), "first": distinct[0] if distinct else None,
            "last": distinct[-1] if distinct else None, "missing": missing,
            "dup": sorted(seq for seq, count in counts.items() if count >= 2),
            "next_seq": None, "unacked": None, "stale_next": None}


def add_state(node, channels, distinct, bad):
    path = node / "state.json"
    if not path.exists() and not path.is_symlink():
        return
    try:
        if path.is_symlink():
            raise ValueError("state symlink")
        state = json.loads(path.read_bytes(), parse_constant=reject_constant)
        if not isinstance(state, dict) or not isinstance(state.get("channels"), dict):
            raise ValueError("state structure")
    except (OSError, ValueError, UnicodeError):
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
        return
    invalid = False
    for name in ("obs", "must"):
        item = state["channels"].get(name)
        if not isinstance(item, dict):
            invalid = True
            continue
        next_seq = item.get("next_seq")
        acked = item.get("acked_upto") if name == "must" else 0
        if type(next_seq) is not int or type(acked) is not int:
            invalid = True
            continue
        result = channels[name]
        result["next_seq"] = next_seq
        result["stale_next"] = (next_seq != result["last"] + 1
                                if result["last"] is not None else None)
        if name == "must":
            result["unacked"] = sum(seq > acked for seq in distinct[name])
    if invalid:
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})


def summarize(node):
    bad = []
    seqs = {name: records(node, name, bad) for name in ("obs", "must")}
    channels = {name: channel_result(seqs[name]) for name in ("obs", "must")}
    distinct = {name: set(seqs[name]) for name in ("obs", "must")}
    add_state(node, channels, distinct, bad)
    bad.sort(key=lambda item: (item["file"], item["line"] or 0, item["why"]))
    return {"v": 1, "channels": channels, "bad": bad}


def main(argv=None):
    args = sys.argv[1:] if argv is None else argv
    if len(args) != 1 or not Path(args[0]).is_dir():
        return 2
    try:
        result = summarize(Path(args[0]))
    except OSError:
        return 2
    print(json.dumps(result, ensure_ascii=True, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
